import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { color, texture as tslTexture, uv, mix, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Textured Plane ---
  const geometry = new PlaneGeometry(1.6, 1); // auto aspect from 512x320
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture
  let textureDispose = () => {};
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      textureDispose = () => {
        tex.dispose();
      };
    });
  }

  // --- Text ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    if (item.text && item.role === 'headline') {
      const textOpts = {
        fontSize: item.typography?.fontSize || 39,
        color: '#e8ecf2',
        align: 'center',
      };
      const textMesh = ctx.fontAtlas.createText(item.text, textOpts);
      // Position in front of plane
      textMesh.position.set(0, 0, 0.01);
      group.add(textMesh);
    }
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureDispose();
    // Dispose any text meshes (if ctx.fontAtlas provides cleanup, but assume automatic)
    group.children.forEach(child => {
      if (child.isMesh && child.material === material) { /* already disposed */ }
      if (child.isGroup && child.userData.cleanup) {
        child.userData.cleanup();
      }
    });
    // Kill GSAP timelines on this node
    gsap.killTweensOf(group);
  };

  return group;
}
